(function(){
  function api(name){
    var scopes=[window];
    try{if(window.parent&&window.parent!==window)scopes.push(window.parent);}catch(e){}
    try{if(window.top&&scopes.indexOf(window.top)<0)scopes.push(window.top);}catch(e){}
    for(var i=0;i<scopes.length;i++){try{if(typeof scopes[i][name]==='function')return scopes[i][name].bind(scopes[i]);}catch(e){}}
    return null;
  }
  var button=document.getElementById('jnStartStory');
  var status=document.getElementById('jnStartStatus');
  button.addEventListener('click',async function(){
    button.disabled=true;status.textContent='姜南替妳推開第二扇門……';
    try{
      var getMessages=api('getChatMessages');
      var setChatMessages=api('setChatMessages');
      if(!getMessages||!setChatMessages)throw new Error('message_api_unavailable');
      var messages=await getMessages(0,{include_swipes:true});
      var opening=messages&&messages[0];
      if(!opening||!Array.isArray(opening.swipes)||typeof opening.swipes[1]==='undefined')throw new Error('second_opening_missing');
      await setChatMessages([{message_id:0,swipe_id:1}],{refresh:'all'});
    }catch(error){
      button.disabled=false;status.textContent='第二開場沒有接上：請確認角色卡的 alternate greeting 尚在。';
      console.error('[姜南開場]',error);
    }
  });
})();
</script>
</body>
