    try {
      var getMessages = findApi('getChatMessages');
      var setMessages = findApi('setChatMessages');
      if (!getMessages || !setMessages) throw new Error('message API unavailable');
      var messages = await getMessages(0, { include_swipes: true });
      var opening = messages && messages[0];
      if (!opening || !Array.isArray(opening.swipes) || opening.swipes[openingId] === undefined) throw new Error('opening swipe missing');
      await setMessages([{ message_id: 0, swipe_id: Number(openingId) }], { refresh: 'all' });
    } catch (e) {
      console.error('[姜南] 切換開場失敗', e);
    }
  };
  window.ylCmd = async function(game) {
    try {
      var text = '【換桌】' + game;
      var createMessages = findApi('createChatMessages');
      if (createMessages) {
        await createMessages([{role:'user', message:text}]);
        return;
      }
      var slash = findApi('triggerSlash');
      if (!slash) throw new Error('message API unavailable');
      await slash('/send ' + text);
    } catch(e) {
      console.error('[ylCmd]', e);
    }
  };

  /* ── 舊樓層靜態化 ── */
  (function checkStale() {
    try {
      var myId = typeof getCurrentMessageId === 'function' ? getCurrentMessageId() : -1;
      if (myId < 0) return;
      if (myId === 0) return;
      /* 取聊天長度：嘗試 TavernHelper API，取不到就用 DOM 計數 */
      var chatLen = -1;
      try {
        if (typeof getChatLength === 'function') {
          chatLen = getChatLength();
        }
      } catch(e2) {}
      if (chatLen < 0) {
        try {
          chatLen = window.parent.document.querySelectorAll('.mes[mesid]').length;
        } catch(e3) {}
      }
      if (chatLen > 0 && myId < chatLen - 2) {
        var btns = document.querySelectorAll('.yl-btn');
        for (var i = 0; i < btns.length; i++) {
          btns[i].classList.add('yl-disabled');
        }
        document.getElementById('ylStale').style.display = '';
      }
    } catch(e) {}
  })();
})();
</script>
</body>

