<script>
(function(){
  /* ── 解碼資料 ── */
  var D;
  try {
    D = JSON.parse(decodeURIComponent(escape(atob('$1'))));
  } catch(e) {
    document.getElementById('bpRoot').textContent = '[bet panel decode error]';
    return;
  }

  var table = D.t;
  var funds = D.f || 0;
  var ledger = D.l || {};

  /* ── 注項定義 ── */
  var OPT_MAP = {
    '百家樂': ['莊','閒','和','莊對','閒對'],
    '輪盤':       ['紅','黑','單','雙','大','小','1打','2打','3打'],
    '骰寶':       ['大','小','全圍','1','2','3','4','5','6'],
