    '龍虎':       ['龍','虎','和'],
    '射龍門': [],
    '牛牛':       [],
    '簽泥碼': [],
    '還債':       []
  };

  var isSettle = (table === '簽泥碼' || table === '還債');
  var opts = OPT_MAP[table] || [];
  var needOpt = opts.length > 0;
  var selectedOpt = needOpt ? null : '';
  var selectedAmt = 0;

  var CHIPS = [
    {v:500,  l:'500'},
    {v:1000, l:'1k'},
    {v:5000, l:'5k'},
    {v:10000,l:'1w'},
    {v:50000,l:'5w'}
  ];

  /* ── 渲染 ── */
  var root = document.getElementById('bpRoot');
  var h = '';

  /* 標題 */
  h += '<div class="bp-title">';
  h += '<div class="bp-title-icon">&#x1F3B2;</div>';
  h += '<div class="bp-title-text">' + esc(table) + '</div>';
  if (isSettle) {
    h += '<div class="bp-title-sub">SETTLEMENT</div>';
  } else {
    h += '<div class="bp-title-sub">PLACE YOUR BET</div>';
  }
  h += '<div class="bp-title-line"></div>';
  h += '</div>';

  /* 注項區（有選項時顯示） */
  if (needOpt) {
    h += '<div class="bp-section">';
    h += '<div class="bp-label">' + (isSettle ? '操作' : '注項') + '</div>';
    h += '<div class="bp-opts" id="bpOpts">';
    for (var i = 0; i < opts.length; i++) {
      h += '<div class="bp-opt" data-opt="' + esc(opts[i]) + '" onclick="bpSelOpt(this)">' + esc(opts[i]) + '</div>';
    }
    h += '</div>';

    /* 輪盤單號輸入 */
    if (table === '輪盤') {
      h += '<div class="bp-custom-row">';
      h += '<input type="number" class="bp-custom-input" id="bpRouNum" placeholder="單號 0-36" min="0" max="36" oninput="bpRouInput(this)">';
      h += '</div>';
    }
    h += '</div>';
  }

  /* 金額區 */
  h += '<div class="bp-section">';
  h += '<div class="bp-label">' + (isSettle ? '金額' : '籌碼') + '</div>';
  h += '<div class="bp-chips" id="bpChips">';
  for (var j = 0; j < CHIPS.length; j++) {
    h += '<div class="bp-chip" data-amt="' + CHIPS[j].v + '" onclick="bpSelAmt(this)">' + CHIPS[j].l + '</div>';
  }
  h += '</div>';
  h += '<div class="bp-custom-row">';
  h += '<input type="number" class="bp-custom-input" id="bpCustomAmt" placeholder="自訂金額" min="1" oninput="bpCustomInput(this)">';
  h += '</div>';
  h += '</div>';

  /* 開局按鈕 */
  h += '<div class="bp-section">';
  h += '<button class="bp-go" id="bpGo" onclick="bpGo()" disabled>' + (isSettle ? '確認' : '開局') + '</button>';
  h += '<div class="bp-funds">';
  h += '可用 ' + funds.toLocaleString();
  if (ledger['泥碼'] > 0) {
    h += '（泥碼 ' + ledger['泥碼'].toLocaleString() + '）';
  }
  h += '</div>';
  h += '</div>';

  root.innerHTML = h;

  function esc(s) {
    var d = document.createElement('div');
    d.textContent = s;
    return d.innerHTML;
  }

  /* ── 互動 ── */
  window.bpSelOpt = function(el) {
    var all = document.querySelectorAll('#bpOpts .bp-opt');
    for (var i = 0; i < all.length; i++) all[i].classList.remove('selected');
    el.classList.add('selected');
    selectedOpt = el.getAttribute('data-opt');
    /* 清除輪盤單號輸入（如果選了固定注項） */
    var rn = document.getElementById('bpRouNum');
    if (rn) rn.value = '';
    checkReady();
  };

  window.bpRouInput = function(el) {
    var v = parseInt(el.value);
    if (!isNaN(v) && v >= 0 && v <= 36) {
      /* 清除固定注項選中 */
      var all = document.querySelectorAll('#bpOpts .bp-opt');
      for (var i = 0; i < all.length; i++) all[i].classList.remove('selected');
      selectedOpt = String(v);
    } else {
      selectedOpt = null;
    }
    checkReady();
  };

  window.bpSelAmt = function(el) {
    var all = document.querySelectorAll('#bpChips .bp-chip');
    for (var i = 0; i < all.length; i++) all[i].classList.remove('selected');
    el.classList.add('selected');
    selectedAmt = parseInt(el.getAttribute('data-amt'));
    document.getElementById('bpCustomAmt').value = '';
    checkReady();
  };

  window.bpCustomInput = function(el) {
    var v = parseInt(el.value);
    if (!isNaN(v) && v > 0) {
      var all = document.querySelectorAll('#bpChips .bp-chip');
      for (var i = 0; i < all.length; i++) all[i].classList.remove('selected');
      selectedAmt = v;
    } else {
      selectedAmt = 0;
    }
    checkReady();
  };

  function checkReady() {
    var ready = selectedAmt > 0 && (needOpt ? selectedOpt !== null : true);
    document.getElementById('bpGo').disabled = !ready;
  }

  window.bpGo = function() {
    if (selectedAmt <= 0) return;
    if (needOpt && selectedOpt === null) return;

    var btn = document.getElementById('bpGo');
    btn.disabled = true;
    btn.textContent = '處理中…';

    /* 功能結構參考：《世事一場大夢》 */
    var msg = {
      type: isSettle ? 'jn-settle' : 'jn-bet',
      t: table,
      bt: selectedOpt || '',
      ba: selectedAmt,
      n: D.n
    };

    /* 防禦鏈：window.parent.postMessage → window.top.postMessage → fallback */
    try {
      if (window.parent && window.parent !== window) {
        window.parent.postMessage(msg, '*');
      } else if (window.top && window.top !== window) {
        window.top.postMessage(msg, '*');
      }
    } catch(e) {
      console.error('[BetPanel] postMessage failed', e);
    }

    /* 靜態化：發送後禁用面板 */
    setTimeout(function() {
      var els = document.querySelectorAll('.bp-opt, .bp-chip, .bp-custom-input');
      for (var i = 0; i < els.length; i++) {
        els[i].classList.add('bp-disabled');
        if (els[i].tagName === 'INPUT') els[i].disabled = true;
      }
      btn.textContent = isSettle ? '已確認' : '已開局';
    }, 300);
  };

  /* ── 舊樓層靜態化 ── */
  (function checkStale() {
    try {
      var myId = typeof getCurrentMessageId === 'function' ? getCurrentMessageId() : -1;
      if (myId < 0) return;
      var chatLen = -1;
      try {
        if (typeof getChatLength === 'function') chatLen = getChatLength();
      } catch(e2) {}
      if (chatLen < 0) {
        try {
          chatLen = window.parent.document.querySelectorAll('.mes[mesid]').length;
        } catch(e3) {}
      }
      if (chatLen > 0 && myId < chatLen - 2) {
        var all = document.querySelectorAll('.bp-opt, .bp-chip, .bp-custom-input, .bp-go');
        for (var i = 0; i < all.length; i++) {
          all[i].classList.add('bp-disabled');
          if (all[i].tagName === 'INPUT' || all[i].tagName === 'BUTTON') all[i].disabled = true;
        }
        document.getElementById('bpStale').style.display = '';
      }
    } catch(e) {}
  })();
})();
</script>
</body>

