scripts.content:
import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  姜南: z.object({
    心動: z.coerce.number().prefault(0),
    愧疚: z.coerce.number().prefault(0),
    面具: z.coerce.number().prefault(100),
    風聲已起: z.boolean().prefault(false),
  }).transform(data => {
    let 心動 = Math.round(_.clamp(data.心動, 0, 100));
    let 愧疚 = Math.round(_.clamp(data.愧疚, 0, 100));
    let 面具 = Math.round(_.clamp(data.面具, 0, 100));
    /* 聯動條令：面具完好時不讓自己越線 */
    if (面具 > 50) {
      心動 = Math.min(心動, 69);
    }
    /* 劇情鎖：未經風聲事件不會愛到底 */
    if (!data.風聲已起) {
      心動 = Math.min(心動, 89);
    }
    return { 心動, 愧疚, 面具, 風聲已起: data.風聲已起 };
  }),
  帳本: z.object({
    本金: z.coerce.number().prefault(35000),
    泥碼: z.coerce.number().prefault(0),
    欠債: z.coerce.number().prefault(3500000),
  }).transform(data => ({
    本金: Math.max(0, Math.round(data.本金)),
    泥碼: Math.max(0, Math.round(data.泥碼)),
    欠債: Math.max(0, Math.round(data.欠債)),
  })),
});

function clampEmotionStep(newVars, oldVars, calibration) {
  var next = newVars && newVars.stat_data && newVars.stat_data.姜南;
  var prev = oldVars && oldVars.stat_data && oldVars.stat_data.姜南;
  if (!next || !prev) return newVars;

  ['心動', '愧疚', '面具'].forEach(function(key) {
    var oldValue = Number(prev[key]);
    var newValue = Number(next[key]);
    if (!Number.isFinite(oldValue)) oldValue = key === '面具' ? 100 : 0;
    if (!Number.isFinite(newValue)) newValue = oldValue;
    newValue = Math.round(Math.max(0, Math.min(100, newValue)));
    if (!calibration) newValue = Math.max(oldValue - 3, Math.min(oldValue + 3, newValue));
    next[key] = Math.round(Math.max(0, Math.min(100, newValue)));
  });

  if (next.面具 > 50) next.心動 = Math.min(next.心動, 69);
  if (next.風聲已起 !== true) next.心動 = Math.min(next.心動, 89);
  return newVars;
}

$(() => {
  registerMvuSchema(Schema);
  try {
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, function(newVars, oldVars) {
      var messageId = -1;
      try { if (typeof getLastMessageId === 'function') messageId = getLastMessageId(); } catch (e) {}
      clampEmotionStep(newVars, oldVars, messageId >= 0 && messageId <= 2);
    });
  } catch (e) { console.log('[姜南] 情緒步進保護未掛載', e); }
});

/*
  洋樓選單按鈕腳本
  按鈕名：🏮 洋樓
  行為：發送帶標記的使用者訊息 → 美化正則渲染成洋樓平面圖選單
  機制：走 /send 斜線指令插入訊息，不觸發 AI 生成

  ⚠ 禁止簡繁轉換：按鈕名「🏮 洋樓」必須維持此名稱，
    不可被轉為「🏮 洋楼」或任何其他字型。
    按鈕事件由 getButtonEvent 以名稱字串配對，轉換即死鈕。
*/
$(() => {
  /* 禁止簡繁轉換：下列按鈕名稱為固定字串 */
  eventOn(getButtonEvent('🏮 洋樓'), async () => {
    try {
      await triggerSlash('/send <yanglou_menu/>');
    } catch (e) {
      console.error('[洋樓選單]', e);
    }
  });
});

$(async function() {
  /* ══════════════════════════════════════════════════════
   * 姜南真骰引擎 v2.1.1
   * 七戲公正 RNG ＋ 帳本直寫 ＋ 換桌世界書切換
   * ══════════════════════════════════════════════════════
   * 禁止簡繁轉換：所有按鈕名、條目名以本檔為準
   * 賭戀分離保證：本檔不讀取、不引用任何感情值
   * ══════════════════════════════════════════════════════ */

  await waitGlobalInitialized('Mvu');

  /* ────────── 1. 常量 ────────── */

  var MANAGED_RULES = [
    '【規則】百家樂',
    '【規則】德州撲克',
    '【規則】二十一點',
    '【規則】輪盤',
    '【規則】骰寶',
    '【規則】拉霸機',
    '【規則】捕魚機',
    '【規則】牌九',
    '【規則】射龍門龍虎牛牛',
    '【規則】花旗骰'
  ];

  var TABLE_MAP = {
    '拉霸':       '【規則】拉霸機',
    '百家樂': MANAGED_RULES[0],
    '輪盤':       '【規則】輪盤',
    '骰寶':       '【規則】骰寶',
    '龍虎':       '【規則】射龍門龍虎牛牛',
    '射龍門': '【規則】射龍門龍虎牛牛',
    '牛牛':       '【規則】射龍門龍虎牛牛',
    '德撲':       '【規則】德州撲克',
    '德撲敘事桌': '【規則】德州撲克',
    '二十一點':   '【規則】二十一點',
    '捕魚機':     '【規則】捕魚機',
    '牌九':       '【規則】牌九',
    '花旗骰':     '【規則】花旗骰'
  };

  var ENGINE_GAMES = [
    '拉霸','百家樂','輪盤',
    '骰寶','龍虎','射龍門','牛牛'
  ];

  var NARRATIVE_GAMES = ['德撲','德撲敘事桌','二十一點','捕魚機','牌九','花旗骰'];

  var BET_OPTIONS = {
    '百家樂': ['莊','閒','和','莊對','閒對'],
