  var floorPending = Object.create(null);

  function safeClone(value) {
    return JSON.parse(JSON.stringify(value));
  }

  function makeFloorKey() {
    var messageId = -1;
    var stamp = '';
    try {
      if (typeof getLastMessageId === 'function') messageId = Number(getLastMessageId());
    } catch (e) {}
    try {
      var ctx = typeof SillyTavern !== 'undefined' && SillyTavern.getContext ? SillyTavern.getContext() : null;
      var chat = ctx && Array.isArray(ctx.chat) ? ctx.chat : null;
      if ((!Number.isInteger(messageId) || messageId < 0) && chat) messageId = chat.length - 1;
      var message = chat && messageId >= 0 ? chat[messageId] : null;
      stamp = message && (message.send_date || message.gen_started || message.gen_finished || message.mes_id) || '';
    } catch (e2) {}
    if (!Number.isInteger(messageId) || messageId < 0) throw new Error('floor_identity_invalid');
    if (!stamp) stamp = 'message-' + messageId;
    return 'floor:' + messageId + ':' + encodeURIComponent(String(stamp));
  }

  function readSystemState() {
    try {
      if (typeof getVariables !== 'function') return {};
      var vars = getVariables({type:'chat'}) || {};
      return safeClone(vars['姜南系統'] || {});
    } catch (e) { return {}; }
  }

  async function writeSystemState(state) {
    if (typeof insertOrAssignVariables !== 'function') throw new Error('chat_variable_writer_unavailable');
    await Promise.resolve(insertOrAssignVariables({'姜南系統': safeClone(state)}, {type:'chat'}));
  }

  function readFloorResultByKey(floorKey) {
    var state = readSystemState();
    var floors = state['樓層結果'] || {};
    return floors[floorKey] ? safeClone(floors[floorKey]) : null;
  }

  async function writeFloorResult(record) {
    var state = readSystemState();
    var floors = Object.assign({}, state['樓層結果'] || {});
    floors[record.floorKey] = safeClone(record);
    state['樓層結果'] = floors;
    state['最近事件'] = {
      type: 'game', id: record.id, floorKey: record.floorKey,
      game: record.table, betType: record.betType, amount: record.amount,
      delta: record.delta, summary: record.text,
      rule: '此事件提供姜南反應的情境；不得把輸贏直接換算為心動。'
    };
    state['當前桌'] = record.table;
    await writeSystemState(state);
    var verified = readFloorResultByKey(record.floorKey);
    if (!verified || verified.id !== record.id) throw new Error('floor_result_write_not_verified');
    return verified;
  }

  function floorFailure(code, message) {
    return {ok:false, code:code, message:message};
  }

  function ledgerEqual(left, right) {
    return !!left && !!right && left['本金'] === right['本金'] && left['泥碼'] === right['泥碼'] && left['欠債'] === right['欠債'];
  }

  var RED_NUMBERS = [1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];

  var SLOT_SYMBOLS = ['💎','⭐','🔔','🍒','🍋'];

  /* RTP ~92% 加權結果表 [累積機率, 倍率, 符號, 層級] */
  var SLOT_TABLE = [
    [0.001,  200, [0,0,0], '頭獎'],
    [0.004,  40,  [1,1,1], '大獎'],
    [0.021,  8,   [2,2,2], '中獎'],
    [0.081,  3,   [3,3,3], '小獎'],
    [0.201,  1.5, [3,3,4], '安慰'],
    [0.401,  0.5, [3,4,2], '微中'],
    [1.0,    0,   null,    '未中']
  ];

  /* 牛牛翻倍表（照規則書：牛8=2x, 牛9=3x, 牛牛=5x） */
  var NIU_MULT = [1,1,1,1,1,1,1,1,2,3,5];

  /* QR 入口改由內嵌姜南桌寵建立；本引擎不再送出選單訊息。 */

  /* ────────── 2. RNG 工具 ────────── */  /* ────────── 2. RNG 工具 ────────── */

  function randomUnit() {
    try {
      var cryptoObj = (typeof globalThis !== 'undefined' && globalThis.crypto) ||
        (typeof window !== 'undefined' && window.crypto);
      if (cryptoObj && typeof cryptoObj.getRandomValues === 'function') {
        var buf = new Uint32Array(1);
        cryptoObj.getRandomValues(buf);
        return buf[0] / 4294967296;
      }
    } catch (e) {}
    return Math.random();
  }

  function actionToken() {
    return Date.now().toString(36) + '-' + Math.floor(randomUnit() * 4294967296).toString(36);
  }

  function ri(min, max) {
    var span = max - min + 1;
    try {
      var cryptoObj = (typeof globalThis !== 'undefined' && globalThis.crypto) ||
        (typeof window !== 'undefined' && window.crypto);
      if (cryptoObj && typeof cryptoObj.getRandomValues === 'function') {
        var limit = Math.floor(4294967296 / span) * span;
        var buf = new Uint32Array(1);
        do { cryptoObj.getRandomValues(buf); } while (buf[0] >= limit);
        return min + (buf[0] % span);
      }
    } catch (e) {}
    return Math.floor(randomUnit() * span) + min;
  }

  function shuffle(a) {
    a = a.slice();
    for (var i = a.length - 1; i > 0; i--) {
      var j = ri(0, i);
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  function deck52() {
    var d = [];
    var ss = ['H','D','C','S'];
    for (var s = 0; s < 4; s++)
      for (var r = 1; r <= 13; r++)
        d.push([r, ss[s]]);
    return shuffle(d);
  }

  function dice3() { return [ri(1,6), ri(1,6), ri(1,6)]; }

  function cv(r) { return r >= 10 ? 0 : r; }

  function rn(r) {
    if (r === 1) return 'A';
    if (r === 11) return 'J';
    if (r === 12) return 'Q';
    if (r === 13) return 'K';
    return String(r);
  }

  function ss(s) { return {H:'♥',D:'♦',C:'♣',S:'♠'}[s]||s; }

  function cs(c) { return rn(c[0]) + ss(c[1]); }

  function css(arr) { return arr.map(cs).join(' '); }

  /* ────────── 3. 七戲引擎 ────────── */

  function engBac(bt, ba) {
    var d = deck52(), di = 0;
    var pc = [d[di++], d[di++]];
    var bc = [d[di++], d[di++]];
    var pp = (cv(pc[0][0]) + cv(pc[1][0])) % 10;
    var bp = (cv(bc[0][0]) + cv(bc[1][0])) % 10;
    var nat = pp >= 8 || bp >= 8;

    if (!nat) {
      var drew = false, pt = null;
      if (pp <= 5) {
        pt = d[di++]; pc.push(pt); pp = (pp + cv(pt[0])) % 10; drew = true;
      }
      if (!drew) {
        if (bp <= 5) { var t = d[di++]; bc.push(t); bp = (bp + cv(t[0])) % 10; }
      } else {
        var pv = cv(pt[0]), dr = false;
        if (bp <= 2) dr = true;
        else if (bp === 3 && pv !== 8) dr = true;
        else if (bp === 4 && pv >= 2 && pv <= 7) dr = true;
        else if (bp === 5 && pv >= 4 && pv <= 7) dr = true;
        else if (bp === 6 && (pv === 6 || pv === 7)) dr = true;
        if (dr) { var t2 = d[di++]; bc.push(t2); bp = (bp + cv(t2[0])) % 10; }
      }
    }

    var w = bp > pp ? 'banker' : pp > bp ? 'player' : 'tie';
    var pay = -ba, push = false;

    if (bt === '莊') {
      if (w === 'banker') pay = Math.floor(ba * 0.95);
      else if (w === 'tie') { pay = 0; push = true; }
    } else if (bt === '閒') {
      if (w === 'player') pay = ba;
      else if (w === 'tie') { pay = 0; push = true; }
    } else if (bt === '和') {
      if (w === 'tie') pay = ba * 8;
    } else if (bt === '莊對') {
      if (bc[0][0] === bc[1][0]) pay = ba * 11;
    } else if (bt === '閒對') {
      if (pc[0][0] === pc[1][0]) pay = ba * 11;
    }

    return { g:'bac', r:{bc:bc,bp:bp,pc:pc,pp:pp,w:w,nat:nat}, payout:pay, push:push };
  }

  function engRou(bt, ba) {
    var n = ri(0, 36);
    var c = n === 0 ? 'green' : RED_NUMBERS.indexOf(n) >= 0 ? 'red' : 'black';
    var pay = -ba;
    var num = parseInt(bt);

    if (!isNaN(num) && num >= 0 && num <= 36) {
      if (n === num) pay = ba * 35;
    } else if (bt === '紅') {
      if (c === 'red') pay = ba;
    } else if (bt === '黑') {
      if (c === 'black') pay = ba;
    } else if (bt === '單') {
      if (n > 0 && n % 2 === 1) pay = ba;
    } else if (bt === '雙') {
      if (n > 0 && n % 2 === 0) pay = ba;
    } else if (bt === '大') {
      if (n >= 19) pay = ba;
    } else if (bt === '小') {
      if (n >= 1 && n <= 18) pay = ba;
    } else if (bt === '1打') {
      if (n >= 1 && n <= 12) pay = ba * 2;
    } else if (bt === '2打') {
      if (n >= 13 && n <= 24) pay = ba * 2;
    } else if (bt === '3打') {
      if (n >= 25 && n <= 36) pay = ba * 2;
    }

    return { g:'rou', r:{n:n,c:c}, payout:pay, push:false };
  }

  function engSic(bt, ba) {
    var d = dice3(), t = d[0]+d[1]+d[2];
    var triple = d[0]===d[1] && d[1]===d[2];
    var pay = -ba;

    if (bt === '大') {
      if (t >= 11 && t <= 17 && !triple) pay = ba;
    } else if (bt === '小') {
      if (t >= 4 && t <= 10 && !triple) pay = ba;
    } else if (bt === '全圍') {
      if (triple) pay = ba * 24;
    } else {
      var tn = parseInt(bt);
      if (!isNaN(tn) && tn >= 1 && tn <= 6) {
        var cnt = 0;
        for (var i = 0; i < 3; i++) if (d[i] === tn) cnt++;
        if (cnt === 1) pay = ba;
        else if (cnt === 2) pay = ba * 2;
        else if (cnt === 3) pay = ba * 3;
      }
    }

    return { g:'sic', r:{d:d,t:t,triple:triple}, payout:pay, push:false };
  }

  function engSlo(ba) {
    var roll = randomUnit(), tier = SLOT_TABLE[SLOT_TABLE.length - 1];
    for (var i = 0; i < SLOT_TABLE.length; i++) {
      if (roll < SLOT_TABLE[i][0]) { tier = SLOT_TABLE[i]; break; }
    }

    var syms;
    if (tier[2]) {
      syms = tier[2].map(function(idx) { return SLOT_SYMBOLS[idx]; });
    } else {
      do {
        syms = [SLOT_SYMBOLS[ri(0,4)], SLOT_SYMBOLS[ri(0,4)], SLOT_SYMBOLS[ri(0,4)]];
      } while (syms[0]===syms[1] && syms[1]===syms[2]);
    }

    var pay = tier[1] > 0 ? Math.round(ba * tier[1]) - ba : -ba;
    return { g:'slo', r:{s:syms, tier:tier[3], mult:tier[1]}, payout:pay, push:false };
  }

  function engRdg(ba) {
    var dk = deck52();
    var g1 = dk[0], g2 = dk[1], shot = dk[2];
    var lo = Math.min(g1[0], g2[0]), hi = Math.max(g1[0], g2[0]);
    var sr = shot[0];
    var hit = (sr === lo || sr === hi);
    var inG = sr > lo && sr < hi;
    var pay = hit ? -ba * 2 : inG ? ba : -ba;

    return { g:'rdg', r:{g1:g1,g2:g2,shot:shot,lo:lo,hi:hi,hit:hit,inG:inG}, payout:pay, push:false };
  }

  function engDrt(bt, ba) {
    var dk = deck52();
    var dr = dk[0], ti = dk[1];
    var w = dr[0] > ti[0] ? 'dragon' : ti[0] > dr[0] ? 'tiger' : 'tie';
    var pay = -ba;

    if (bt === '龍' && w === 'dragon') pay = ba;
    else if (bt === '虎' && w === 'tiger') pay = ba;
    else if (bt === '和' && w === 'tie') pay = ba * 8;
    else if (w === 'tie' && bt !== '和') pay = -Math.floor(ba / 2);

    return { g:'drt', r:{dragon:dr,tiger:ti,w:w}, payout:pay, push:false };
  }

  function engNiu(ba) {
    var dk = deck52();
    var pc = dk.slice(0, 5), dc = dk.slice(5, 10);

    function nv(r) { return r > 10 ? 10 : r; }
    function calc(cards) {
      for (var i = 0; i < 3; i++)
        for (var j = i+1; j < 4; j++)
          for (var k = j+1; k < 5; k++) {
            if ((nv(cards[i][0])+nv(cards[j][0])+nv(cards[k][0])) % 10 === 0) {
              var rest = [];
              for (var m = 0; m < 5; m++) if (m!==i&&m!==j&&m!==k) rest.push(cards[m]);
              var s2 = (nv(rest[0][0])+nv(rest[1][0])) % 10;
              return s2 === 0 ? 10 : s2;
            }
          }
      return 0;
    }

    var pn = calc(pc), dn = calc(dc);
    var pw;
    if (pn > dn) pw = true;
    else if (pn < dn) pw = false;
    else {
      var pMax = Math.max.apply(null, pc.map(function(c){return c[0];}));
      var dMax = Math.max.apply(null, dc.map(function(c){return c[0];}));
      pw = pMax > dMax;
    }

    var mult = NIU_MULT[pw ? pn : dn] || 1;
    var pay = pw ? ba * mult : -ba * mult;

    return { g:'niu', r:{pc:pc,dc:dc,pn:pn,dn:dn,pw:pw}, payout:pay, push:false };
  }

  /* ────────── 4. 帳本操作 ────────── */

  function readLedger() {
    try {
      var d = Mvu.getMvuData({type:'message', message_id:'latest'});
      if (d && d.stat_data && d.stat_data['帳本']) return d.stat_data['帳本'];
    } catch(e) {}
    return {'本金':35000,'泥碼':0,'欠債':3500000};
  }

  async function writeLedger(nL) {
    try {
      var d = Mvu.getMvuData({type:'message', message_id:'latest'});
      if (!d||!d.stat_data) return false;
      var values = [nL['本金'], nL['泥碼'], nL['欠債']];
      for (var i = 0; i < values.length; i++) {
        if (!Number.isFinite(values[i]) || values[i] < 0 || values[i] > Number.MAX_SAFE_INTEGER) return false;
      }
      d.stat_data['帳本'] = {
        '本金': Math.max(0, Math.round(nL['本金'])),
        '泥碼': Math.max(0, Math.round(nL['泥碼'])),
        '欠債': Math.max(0, Math.round(nL['欠債']))
      };
      engineWritingLedger = true;
      try {
        await Mvu.replaceMvuData(d, {type:'message', message_id:'latest'});
        return true;
      } finally {
        engineWritingLedger = false;
      }
    } catch(e) { return false; }
  }

  function deduct(ledger, amt) {
    var fm = Math.min(ledger['泥碼']||0, amt);
    return { fm:fm, fp:amt-fm };
  }

  function applyResult(ledger, ded, pay, push) {
    var nL = {
      '本金': ledger['本金'] - ded.fp,
      '泥碼': ledger['泥碼'] - ded.fm,
      '欠債': ledger['欠債']
    };
    if (push || pay === 0) {
      nL['本金'] += ded.fp;
      nL['泥碼'] += ded.fm;
    } else if (pay > 0) {
      nL['泥碼'] += ded.fm;
      nL['本金'] += ded.fp + pay;
    } else if (pay < 0) {
      /* 半輸等部分退還：龍虎和局、拉霸 0.5x 都不能被當成全輸。 */
      var stake = ded.fm + ded.fp;
      var refund = Math.max(0, stake + pay);
      if (refund > 0 && stake > 0) {
        var refundMud = Math.floor(refund * ded.fm / stake);
        nL['泥碼'] += refundMud;
        nL['本金'] += refund - refundMud;
      }
    }
    return nL;
  }

  /* ────────── 5. 結果文字 ────────── */

  var GNAME = {
    bac:'百家樂', rou:'輪盤', sic:'骰寶',
    slo:'拉霸機', rdg:'射龍門',
    drt:'龍虎鬥', niu:'牛牛'
  };
  var WNAME = {banker:'莊贏',player:'閒贏',tie:'和局',
               dragon:'龍贏',tiger:'虎贏'};

  function niuN(v) {
    if (v===0) return '無牛';
    if (v===10) return '牛牛';
    return '牛'+v;
  }

  function resText(game, bt, ba, res, bL, aL) {
    var ln = ['【引擎結果】' + (GNAME[res.g]||game)];
    var r = res.r;

    if (res.g==='bac') {
      ln.push('莊家 '+r.bp+' 點（'+css(r.bc)+'）');
      ln.push('閒家 '+r.pp+' 點（'+css(r.pc)+'）');
      ln.push('結果：'+(WNAME[r.w]||r.w));
      if (r.nat) ln.push('天牌（Natural）');
    } else if (res.g==='rou') {
      ln.push('號碼：'+r.n+'（'+{red:'紅',black:'黑',green:'綠'}[r.c]+'）');
    } else if (res.g==='sic') {
      ln.push('骰面：'+r.d.join('、')+'（合計 '+r.t+'）');
      if (r.triple) ln.push('全圍！');
    } else if (res.g==='slo') {
      ln.push('轉輪：'+r.s.join(' '));
      ln.push(r.tier+(r.mult>0?'（'+r.mult+'倍）':''));
    } else if (res.g==='rdg') {
      ln.push('門柱：'+cs(r.g1)+' — '+cs(r.g2));
      ln.push('射門：'+cs(r.shot));
      if (r.hit) ln.push('撞柱！包賠雙倍');
      else if (r.inG) ln.push('進門');
      else ln.push('出界');
    } else if (res.g==='drt') {
      ln.push('龍：'+cs(r.dragon)+'　虎：'+cs(r.tiger));
      ln.push('結果：'+(WNAME[r.w]||r.w));
    } else if (res.g==='niu') {
      ln.push('玩家：'+css(r.pc)+'→'+niuN(r.pn));
      ln.push('莊家：'+css(r.dc)+'→'+niuN(r.dn));
      ln.push(r.pw?'玩家勝':'莊家勝');
    }

    var net = res.payout;
    if (res.push) ln.push('下注 '+ba+'→退注');
    else if (net>0) ln.push('下注 '+ba+'→贏 '+Math.round(net));
    else ln.push('下注 '+ba+'→輸 '+Math.abs(Math.round(net)));

    ln.push('帳本：本金 '+aL['本金']+
            '｜泥碼 '+aL['泥碼']+
            '｜欠債 '+aL['欠債']);
    return ln.join('\n');
  }

  /* ────────── 6. 世界書切換 ────────── */

  async function getWb() {
    try {
      if (typeof TavernHelper!=='undefined' && TavernHelper.getCurrentCharPrimaryLorebook)
        return await TavernHelper.getCurrentCharPrimaryLorebook();
    } catch(e){}
    try {
      var n = await getCharWorldbookNames('current');
      return n && n.primary;
    } catch(e){}
    return null;
  }

  async function switchRules(target, quiet) {
    var wb = await getWb();
    if (!wb) { toastr.error('找不到世界書','換桌失敗'); return false; }
    try {
      var entries = await TavernHelper.getLorebookEntries(wb);
      var updates = [], logs = [];
      (entries||[]).forEach(function(e) {
        var c = e.comment||'';
        if (MANAGED_RULES.indexOf(c)<0) return;
        var want = (c === target);
        if (e.enabled !== want) {
          updates.push({uid:e.uid, enabled:want});
          logs.push((want?'✅':'🚫')+' '+c);
        }
      });
      if (updates.length>0) await TavernHelper.setLorebookEntries(wb, updates);
      if (logs.length>0 && !quiet) {
        toastr.success('📖 已切換至'+(target||'離桌')+'<br>'+logs.join('<br>'),
          '世界書切換', {timeOut:4000,escapeHtml:false,preventDuplicates:true});
      }
      return true;
    } catch(e) {
      toastr.error('世界書寫入失敗：'+(e.message||e),'換桌失敗');
      return false;
    }
  }

  async function enableAll() {
    var wb = await getWb();
    if (!wb) { toastr.error('找不到世界書','規則全開失敗'); return; }
    try {
      var entries = await TavernHelper.getLorebookEntries(wb);
      var updates = [];
      (entries||[]).forEach(function(e) {
        if (MANAGED_RULES.indexOf(e.comment||'')<0) return;
        if (!e.enabled) updates.push({uid:e.uid,enabled:true});
      });
      if (updates.length>0) {
        await TavernHelper.setLorebookEntries(wb, updates);
        toastr.success('📖 十本規則書已全部開啟','規則全開',{timeOut:3000});
      } else {
        toastr.info('📖 規則書已全部開啟，無需變更','規則全開',{timeOut:3000});
      }
