  /* ────────── 7. 下注流程（聊天內面板；功能結構參考：《世事一場大夢》） ────────── */

  /* 舊按鈕保留為相容入口，但不再往聊天樓層送面板訊息。 */
  async function showBetPanel(table) {
    try {
