  async function handleBet() {
    if (!currentTable || ENGINE_GAMES.indexOf(currentTable)<0) {
      if (currentTable==='簽泥碼') return showBetPanel('簽泥碼');
      if (currentTable==='還債') return showBetPanel('還債');
      if (NARRATIVE_GAMES.indexOf(currentTable)>=0) {
        toastr.info(currentTable+'由姜南與模型敘事裁定，請直接說出行動','敘事桌');
        return;
      }
      toastr.warning('請先從洋樓選單選擇一張桌子','未入座');
      return;
    }
    showBetPanel(currentTable);
  }

  /* 處理來自面板的下注（postMessage 觸發） */
  async function processBet(table, bt, ba) {
    var floorKey;
    try { floorKey = makeFloorKey(); }
    catch (identityError) { return floorFailure('floor_identity_invalid', '無法辨識目前聊天樓層，本局沒有結算。'); }

    var locked = readFloorResultByKey(floorKey);
    if (locked) return {ok:true, code:'floor_result_locked', replayed:true, record:locked};
    if (floorPending[floorKey]) return floorPending[floorKey];

    var operation = (async function() {
      var secondCheck = readFloorResultByKey(floorKey);
      if (secondCheck) return {ok:true, code:'floor_result_locked', replayed:true, record:secondCheck};

      ba = Math.round(Number(ba));
      bt = String(bt || '');
      if (table !== currentTable || ENGINE_GAMES.indexOf(table) < 0) {
        return floorFailure('table_changed', '桌台已變更，請回遊戲清單重新選擇。');
      }
      if (!Number.isFinite(ba) || ba <= 0 || ba > Math.floor(Number.MAX_SAFE_INTEGER / 200)) {
        return floorFailure('amount_invalid', '金額必須為安全範圍內的正整數。');
      }
      var allowed = BET_OPTIONS[table] || [];
      var rouletteNumber = table === '輪盤' && /^(?:[0-9]|[12][0-9]|3[0-6])$/.test(bt);
      if (allowed.length > 0 && allowed.indexOf(bt) < 0 && !rouletteNumber) {
        return floorFailure('bet_type_invalid', '這張桌沒有此注項。');
      }

      var ledger = readLedger();
      var funds = (ledger['泥碼'] || 0) + (ledger['本金'] || 0);
      if (table === '牛牛' && ba * 5 > funds) return floorFailure('guarantee_insufficient', '牛牛需保留最大五倍賠率的保證金。');
      if (table === '射龍門' && ba * 2 > funds) return floorFailure('guarantee_insufficient', '射龍門需保留撞柱雙倍罰款的保證金。');
      if (table !== '牛牛' && table !== '射龍門' && ba > funds) return floorFailure('funds_insufficient', '資金不足，請先處理帳本。');

      var ded = deduct(ledger, ba);
      var res;
      if (table === '百家樂') res = engBac(bt, ba);
      else if (table === '輪盤') res = engRou(bt, ba);
      else if (table === '骰寶') res = engSic(bt, ba);
      else if (table === '拉霸') res = engSlo(ba);
      else if (table === '射龍門') res = engRdg(ba);
      else if (table === '龍虎') res = engDrt(bt, ba);
      else if (table === '牛牛') res = engNiu(ba);
      if (!res) return floorFailure('engine_result_missing', '真骰引擎沒有產生結果。');

      var actualPay = res.payout;
      if (res.g === 'rdg' && res.r.hit) ded = deduct(ledger, ba * 2);
      if (res.g === 'niu' && !res.r.pw) ded = deduct(ledger, ba * (NIU_MULT[res.r.dn] || 1));
      var nextLedger = applyResult(ledger, ded, actualPay, res.push);
      var text = resText(table, bt, ba, res, ledger, nextLedger);
      var record = {
        version: 2, status: 'settled', id: actionToken(), floorKey: floorKey,
        table: table, betType: bt, amount: ba, delta: Math.round(actualPay), text: text,
        result: safeClone(res), beforeLedger: safeClone(ledger), afterLedger: safeClone(nextLedger),
        settledAt: new Date().toISOString()
      };

      /* 帳本先寫、鎖後寫；鎖失敗就完整回復帳本，不留下半筆交易。 */
      if (!await writeLedger(nextLedger)) return floorFailure('ledger_write_failed', '帳本寫入失敗，本局沒有成立。');
      try {
        var persisted = await writeFloorResult(record);
        var readBack = readLedger();
        if (!ledgerEqual(readBack, nextLedger)) throw new Error('ledger_readback_mismatch');
        return {ok:true, code:'settled', replayed:false, record:persisted};
      } catch (persistError) {
        await writeLedger(ledger);
        return floorFailure('floor_lock_write_failed', '結果鎖寫入失敗，帳本已回復；本局沒有成立。');
      }
    })();

    floorPending[floorKey] = operation;
    try { return await operation; }
    finally { delete floorPending[floorKey]; }
  }

  /* 處理來自面板的結算（簽泥碼／還債） */  /* 處理來自面板的結算（簽泥碼／還債） */
  async function processSettle(action, amt) {
    amt = Math.round(Number(amt));
    var ledger = readLedger();

    if (!Number.isFinite(amt) || amt <= 0 || amt > Number.MAX_SAFE_INTEGER) {
      toastr.error('金額必須為安全範圍內的正整數','結算失敗'); return;
    }

    if (action === 'sign') {
      if (amt > Number.MAX_SAFE_INTEGER - (ledger['泥碼']||0) ||
          amt > Number.MAX_SAFE_INTEGER - (ledger['欠債']||0)) {
        toastr.error('此金額會超出帳本安全範圍','簽泥碼失敗'); return;
      }
      var nL = {
        '本金':ledger['本金'],
        '泥碼':ledger['泥碼']+amt,
        '欠債':ledger['欠債']+amt
      };
      if (!await writeLedger(nL)) {
        toastr.error('帳本寫入失敗，未簽入泥碼','簽泥碼失敗'); return;
      }

      var txt = '【結算】簽泥碼 '+amt+
                '\n泥碼 '+ledger['泥碼']+'→'+nL['泥碼']+
                '｜欠債 '+ledger['欠債']+'→'+nL['欠債'];
      var rd = {g:'settle',type:'sign',amount:amt,
        l:{bp:ledger['本金'],bm:ledger['泥碼'],bd:ledger['欠債'],
           ap:nL['本金'],am:nL['泥碼'],ad:nL['欠債']}};
      var b64 = btoa(unescape(encodeURIComponent(JSON.stringify(rd))));
      if (!await sendMsg('【結算】簽泥碼\n<jn_result data="'+b64+'"/>\n<jn_result_text>\n'+txt+'\n</jn_result_text>')) {
        await writeLedger(ledger);
        toastr.error('結果訊息建立失敗，已嘗試回復結算前帳本','結算失敗'); return;
      }

    } else if (action === 'repay') {
      if (ledger['欠債']<=0) { toastr.info('沒有欠債','還債'); return; }
      if (amt>ledger['本金']) { toastr.error('本金不足','還債失敗'); return; }
      if (amt>ledger['欠債']) amt = ledger['欠債'];

      var nL2 = {
        '本金':ledger['本金']-amt,
        '泥碼':ledger['泥碼'],
        '欠債':ledger['欠債']-amt
      };
      if (!await writeLedger(nL2)) {
        toastr.error('帳本寫入失敗，未執行還債','還債失敗'); return;
      }

      var free = nL2['欠債']===0;
      var txt2 = '【結算】還債 '+amt+
                '\n本金 '+ledger['本金']+'→'+nL2['本金']+
                '｜欠債 '+ledger['欠債']+'→'+nL2['欠債'];
      if (free) txt2 += '\n🆓 欠債歸零——自由結局觸發';
      var rd2 = {g:'settle',type:'repay',amount:amt,freedom:free,
        l:{bp:ledger['本金'],bm:ledger['泥碼'],bd:ledger['欠債'],
           ap:nL2['本金'],am:nL2['泥碼'],ad:nL2['欠債']}};
      var b64_2 = btoa(unescape(encodeURIComponent(JSON.stringify(rd2))));
      if (!await sendMsg('【結算】還債\n<jn_result data="'+b64_2+'"/>\n<jn_result_text>\n'+txt2+'\n</jn_result_text>')) {
        await writeLedger(ledger);
        toastr.error('結果訊息建立失敗，已嘗試回復結算前帳本','結算失敗'); return;
      }
    }
    /* 帳本動作後預設安靜，不自動替 Mini 觸發對話。 */
  }

  /* 優先使用酒館助手訊息 API，不碰 DOM 送出鍵；Slash 只作降級。 */
  /* 功能結構參考：《世事一場大夢》 */
  async function sendMsg(text) {
    try {
      if (typeof createChatMessages === 'function') {
        await createChatMessages([{role:'user', message:text}]);
        return true;
      }
      if (typeof triggerSlash === 'function') {
        await triggerSlash('/send ' + text);
        return true;
      }
      if (typeof window.triggerSlash === 'function') {
        await window.triggerSlash('/send ' + text);
        return true;
      }
    } catch (e) { console.log('[Engine] create result message failed', e); }
    return false;
  }

  /* ────────── 8. 換桌處理 ────────── */

  /* ④ 換桌流程改序：/send（不生成）→ 世界書切換成功 → /trigger AI 接話 */
  async function onSwitch(text) {
    var m = text.match(/【換桌】(.+)/);
    if (!m) return;
    var tgt = m[1].trim();
    pendingAction = null;

    if (tgt === '離桌') {
      currentTable = null;
      rememberTable(null);
      await disableAll();
      toastr.info('已離桌，規則書全關','離桌');
      /* 離桌後讓 AI 接話 */
      if (typeof triggerSlash === 'function') triggerSlash('/trigger');
      return;
    }
    if (tgt==='簽泥碼'||tgt==='還債') {
      currentTable = tgt;
      rememberTable(currentTable);
      /* 結算室不需要遊戲規則，關閉桌規以減少無關動態注入。 */
      await disableAll();
      if (typeof triggerSlash === 'function') triggerSlash('/trigger');
      return;
    }

    var rule = TABLE_MAP[tgt];
    if (!rule) { toastr.warning('未知的桌台：'+tgt,'換桌'); return; }
    var ok = await switchRules(rule);
    if (ok) {
      currentTable = tgt;
      rememberTable(currentTable);
      /* 世界書切換成功後才讓 AI 接話（治了舊 150ms 時序競態） */
      if (typeof triggerSlash === 'function') triggerSlash('/trigger');
    }
    else { toastr.warning('世界書切換失敗，桌台未變更','換桌'); }
  }

  /* ────────── 9. QR 由姜南桌寵以 nosend=true 建立 ────────── */

  /* ────────── 10. 初始化 ────────── */  /* ────────── 10. 初始化 ────────── */

  /* 禁止簡繁轉換：🎲 下注 */
  var evBet = getButtonEvent('🎲 下注');
  eventOn(evBet, function() { handleBet(); });

  /* 禁止簡繁轉換：📖 規則全開 */
  var evRescue = getButtonEvent('📖 規則全開');
  eventOn(evRescue, function() { enableAll(); });

  /* 監聽換桌指令（⑤ getChatMessages 返回陣列，用 [0] 取值） */
  try {
    eventOn('MESSAGE_SENT', function(msgId) {
      setTimeout(async function() {
        try {
          var last = await getChatMessages(-1);
          var t = '';
          /* ⑤ getChatMessages(-1) 回傳陣列，正確取法見 Kit knowledge/api/01-messages.md:31 */
          if (Array.isArray(last) && last.length > 0) {
            t = last[0].mes || last[0].message || '';
          } else if (last && typeof last === 'object' && !Array.isArray(last)) {
            t = last.mes || last.message || '';
          }
          if (typeof last === 'string') t = last;
          if (t.indexOf('【換桌】')>=0) onSwitch(t);
          if (t.indexOf('【規則全開】')>=0) enableAll();
        } catch(e) { console.log('[Engine] MSG_SENT err', e); }
      }, 150);
    });
  } catch(e) { console.log('[Engine] Cannot listen MESSAGE_SENT', e); }

  /* 監聽面板 postMessage（下注面板 → 引擎；功能結構參考：《世事一場大夢》） */
  try {
    window.addEventListener('message', async function(ev) {
      if (!ev.data || typeof ev.data !== 'object') return;
      if (ev.data.type !== 'jn-bet' && ev.data.type !== 'jn-settle') return;
      if (!pendingAction || ev.data.n !== pendingAction.n || ev.data.t !== pendingAction.t) return;
      pendingAction = null;
      if (ev.data.type === 'jn-bet') {
        await processBet(ev.data.t, ev.data.bt, ev.data.ba);
      } else if (ev.data.type === 'jn-settle') {
        var action = ev.data.t === '簽泥碼' ? 'sign' : 'repay';
        await processSettle(action, ev.data.ba);
      }
    });
  } catch(e) { console.log('[Engine] Cannot listen postMessage', e); }

  /* 攔截模型對帳本的修改 */
  try {
    eventOn(Mvu.events.COMMAND_PARSED, function(vars, commands) {
      if (!currentTable || ENGINE_GAMES.indexOf(currentTable)<0) return;
      for (var i = commands.length-1; i >= 0; i--) {
        var cmd = commands[i] || {};
        var path = typeof cmd.path === 'string' ? cmd.path :
          (Array.isArray(cmd.args) && typeof cmd.args[0] === 'string' ? cmd.args[0] : '');
        if (path.indexOf('帳本')>=0) commands.splice(i,1);
      }
    });
  } catch(e) {}

  /* 第二層保護：真骰回合以生成前帳本為權威，避免未知命令形狀漏網。 */
  try {
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, function(newVars, oldVars) {
      if (!currentTable || ENGINE_GAMES.indexOf(currentTable)<0) return;
      if (engineWritingLedger) return;
      try {
        var oldLedger = oldVars && oldVars.stat_data && oldVars.stat_data['帳本'];
        if (oldLedger && newVars && newVars.stat_data) {
          newVars.stat_data['帳本'] = {
            '本金': oldLedger['本金'],
            '泥碼': oldLedger['泥碼'],
            '欠債': oldLedger['欠債']
          };
        }
      } catch (e) { console.log('[Engine] ledger guard failed', e); }
    });
  } catch(e) {}

  /* CHAT_CHANGED 重新綁定 QR 到新聊天 */
  try {
    eventOn('CHAT_CHANGED', async function() {
      pendingAction = null;
      restoreTable();
      await syncRulesForCurrentTable();
      if (typeof triggerSlash === 'function') {
        triggerSlash('/qr-chat-set-on visible=true ' + QR_SET).catch(function(){});
      }
    });
  } catch(e) {}

  restoreTable();
  await syncRulesForCurrentTable();
  async function selectGameDirect(table) {
    pendingAction = null;
    var rule = TABLE_MAP[table];
    if (!rule) return {ok:false, code:'unknown_table', message:'未知的桌台：' + table};
    var ok = await switchRules(rule);
    if (!ok) return {ok:false, code:'worldbook_switch_failed', message:'規則書切換失敗。'};
    currentTable = table;
    rememberTable(currentTable);
    return {ok:true, table:table, narrative:NARRATIVE_GAMES.indexOf(table) >= 0};
  }

  async function getCurrentFloorResult() {
    try { return readFloorResultByKey(makeFloorKey()); }
    catch (e) { return null; }
  }

  var gameEngineApi = Object.freeze({
    version: '2.1.1',
    engineGames: ENGINE_GAMES.slice(),
    narrativeGames: NARRATIVE_GAMES.slice(),
    betOptions: safeClone(BET_OPTIONS),
    selectGame: selectGameDirect,
    play: function(input) {
      input = input || {};
      return processBet(String(input.table || ''), String(input.betType || ''), Number(input.amount));
    },
    getFloorResult: getCurrentFloorResult,
    getCurrentTable: function() { return currentTable; },
    getLedger: function() { return safeClone(readLedger()); }
  });
  /* 酒館助手每支腳本各住一個 iframe；跨腳本 API 必須發布到 shared global。 */
  globalThis.__JIANGNAN_GAME_ENGINE_V2__ = gameEngineApi;
  if (typeof initializeGlobal === 'function') initializeGlobal('JiangnanGameEngineV2', gameEngineApi);
  else {
    try { window.parent.JiangnanGameEngineV2 = gameEngineApi; }
    catch (e) { globalThis.JiangnanGameEngineV2 = gameEngineApi; }
  }


  console.log('[Engine] init ok, table=' + currentTable);
  /* QR 由姜南桌寵建立。 */
});

