  function letterMood(text, fallback) {
    var value = String(text || '');
    if (/護|別怕|沒走|留下|燈|等妳|回來/.test(value)) return 'guard';
    if (/輸|贏|牌|籌碼|挑|誤會/.test(value)) return 'tease';
    if (/喜歡|想見|靠近|位置|捨不得|特殊/.test(value)) return 'fond';
    return fallback || 'fond';
  }

  function letterExcerptEntry(petState) {
    var config = dialogueConfig().excerpt || {};
    if (!petState.generatedLetter || !petState.letterReadAt || petState.letterUnread === true) return null;
    return {
      id: 'letter-excerpt-' + String(petState.generatedLetterAt || petState.letterReadAt || ''),
      kind: 'letter-excerpt',
      label: config.label || '信件讀後摘句',
      text: String(config.prefix || '') + clipText(petState.generatedLetter, Number(config.maxChars) || 46),
      mood: letterMood(petState.generatedLetter, 'fond'),
      action: 'letters'
    };
  }

  function chooseContextWhisper(options) {
    var settings = options || {};
    var nowMs = Number(settings.nowMs) || Date.now();
    var hour = Number.isFinite(Number(settings.hour)) ? Number(settings.hour) : new Date(nowMs).getHours();
    var state = readState();
    var petState = readPetState();
    var hidden = syncHiddenLetters();
    var forceKind = String(settings.forceKind || '');

    if (!forceKind || forceKind === 'unread') {
      if (petState.letterUnread === true && petState.generatedLetter) {
        var reminder = poolEntry('letterReminder', petState, nowMs);
        reminder.kind = 'letter-reminder';
        reminder.action = 'letters';
        return reminder;
      }
      if (hidden.unreadIds.length) {
        var hiddenId = hidden.unreadIds[0];
        var hiddenLetter = hidden.available.find(function(letter) { return letter.id === hiddenId; });
        var hiddenReminder = poolEntry('letterReminder', petState, nowMs);
        hiddenReminder.kind = 'hidden-letter-reminder';
        hiddenReminder.text = hiddenLetter ? '桌邊多了一封〈' + hiddenLetter.title + '〉。要拆嗎？' : hiddenReminder.text;
        hiddenReminder.action = 'hidden:' + hiddenId;
        hiddenReminder.mood = hiddenLetter && hiddenLetter.mood || hiddenReminder.mood;
        return hiddenReminder;
      }
      if (forceKind === 'unread') return null;
    }

    if (forceKind === 'knock') {
      if (!isKnockHour(hour)) return null;
      var knock = poolEntry('knock', petState, nowMs);
      knock.kind = 'night-knock';
      knock.action = 'home';
      return knock;
    }

    if (forceKind === 'excerpt') return letterExcerptEntry(petState);

    var event = recentGameEvent(state);
    var lastActivity = Math.max(Number(petState.lastInteractionAt) || 0, latestConversationAt(), deskRuntimeStartedAt);
    if (nowMs - lastActivity >= Number(dialogueConfig().cooldowns.inactivityMs || 1200000)) {
      var inactive = poolEntry('inactive', petState, nowMs);
      inactive.kind = 'inactive';
      inactive.action = 'home';
      return inactive;
    }
    if (event && Number(event.delta) > 0) {
      var win = poolEntry('gameWin', petState, nowMs);
      win.kind = 'game-result'; win.action = 'games'; return win;
    }
    if (event && Number(event.delta) < 0) {
      var lose = poolEntry('gameLose', petState, nowMs);
      lose.kind = 'game-result'; lose.action = 'games'; return lose;
    }
    if ((Number(state.jiangnan['心動']) || 0) >= 70) {
      var fond = poolEntry('fond', petState, nowMs);
      fond.kind = 'relationship'; fond.action = 'status'; return fond;
    }
    if ((Number(state.jiangnan['愧疚']) || 0) >= 60) {
      var guard = poolEntry('guard', petState, nowMs);
      guard.kind = 'relationship'; guard.action = 'status'; return guard;
    }
    if (isKnockHour(hour)) {
      var night = poolEntry('night', petState, nowMs);
      night.kind = 'night'; night.action = 'home'; return night;
    }
    if (hour >= 6 && hour < 11) {
      var morning = poolEntry('morning', petState, nowMs);
      morning.kind = 'morning'; morning.action = 'home'; return morning;
    }
    var excerpt = letterExcerptEntry(petState);
    if (excerpt && settings.preferExcerpt === true) return excerpt;
    var ordinary = poolEntry('default', petState, nowMs);
    ordinary.kind = 'context'; ordinary.action = 'home'; return ordinary;
  }

  function showWhisper(entry, options) {
    if (!entry || !entry.text) return null;
    var root = doc.getElementById(ROOT_ID);
    var bubble = root && root.querySelector('.jn-pet-whisper');
    if (!bubble) return null;
    var settings = options || {};
    bubble.textContent = entry.text;
    bubble.setAttribute('data-whisper-action', entry.action || 'home');
    bubble.setAttribute('data-whisper-kind', entry.kind || 'context');
    bubble.classList.add('jn-visible');
    root.setAttribute('data-last-whisper-id', entry.id || '');
    host.clearTimeout(dialogueRuntime.hide);
    dialogueRuntime.hide = host.setTimeout(function() {
      if (bubble) bubble.classList.remove('jn-visible');
    }, Number(settings.visibleMs) || Number(dialogueConfig().cooldowns.visibleMs) || 9000);
    var at = Number(settings.nowMs) || Date.now();
    var patch = { lastWhisperAt: at, lastWhisperId: entry.id || '', lastWhisperKind: entry.kind || 'context' };
    if (entry.kind === 'night-knock') patch.lastKnockAt = at;
    savePetState(patch);
    setPortrait(entry.mood || 'blink', { once: true, returnTo: moodFor(readState()) });
    return entry;
  }

  function evaluateWhisper(options) {
    var settings = options || {};
    var petState = readPetState();
    var config = dialogueConfig();
    var nowMs = Number(settings.nowMs) || Date.now();
    var enabled = typeof petState.bubbleEnabled === 'boolean' ? petState.bubbleEnabled : config.defaults.bubbleEnabled !== false;
    if (!enabled) return null;
    if (doc.visibilityState === 'hidden' && settings.ignoreVisibility !== true) return null;
    if (doc.getElementById(MODAL_ID) && settings.allowOverModal !== true) return null;
    if (settings.bypassCooldown !== true && nowMs - (Number(petState.lastWhisperAt) || 0) < Number(config.cooldowns.proactiveMs || 900000)) return null;
    syncHiddenLetters();
    var entry = chooseContextWhisper(settings);
    if (!entry) return null;
    if (entry.kind === 'night-knock') {
      var knockEnabled = typeof petState.knockEnabled === 'boolean' ? petState.knockEnabled : config.defaults.knockEnabled !== false;
      if (!knockEnabled) return null;
      if (nowMs - (Number(petState.lastKnockAt) || 0) < Number(config.cooldowns.knockMs || 2700000)) return null;
    }
    return showWhisper(entry, { nowMs: nowMs, visibleMs: settings.visibleMs });
  }

  async function generateDeskLine() {
    var petState = readPetState();
    var mode = letterMode(petState);
    if (mode === 'local') throw new Error('「叫他說一句」需要模型。請先在相處設定選酒館主連線或指定副連線。');
    var manual = dialogueConfig().manualLine || {};
    var state = readState();
    var prompt = [
      manual.prompt || '請以姜南口吻只說一句繁體中文。',
      '關係：' + phaseName(state.jiangnan['心動']) + '；心動 ' + money(state.jiangnan['心動']) + '，愧疚 ' + money(state.jiangnan['愧疚']) + '，面具 ' + money(state.jiangnan['面具']) + '。',
      recentConversation(6) ? '最近對話：\n' + recentConversation(6) : ''
    ].filter(Boolean).join('\n\n');
    var result;
    var source;
    if (mode === 'profile') {
      var profiles = getConnectionProfiles();
      var profile = profiles.find(function(item) { return item.id === String(petState.letterProfileId || ''); });
      if (!profile) throw new Error('找不到指定的連線設定檔。請回到相處設定重新選擇副連線。');
      var slash = findApi('triggerSlash');
      if (!slash) throw new Error('酒館指令沒有接上，無法使用指定副連線。');
      var command = '/profile-genstream profile=' + slashQuote(profile.id) + ' reasoning=false length=' + Number(manual.responseLength || 180) + ' generating=' + slashQuote('姜南抬眼看過來……') + ' completed=' + slashQuote('他把話留在桌邊') + ' delay=500 stop=true ' + slashQuote(prompt);
      result = await slash(command);
      source = '指定副連線 · ' + profile.name + (profile.model ? ' · ' + profile.model : '');
    } else {
      var generate = findApi('generate');
      if (generate) result = await generate({ user_input: prompt, should_stream: false, should_silence: true, max_chat_history: 10 });
      else {
        var quiet = findApi('generateQuietPrompt');
        if (!quiet) throw new Error('找不到酒館生成介面；請確認 TavernHelper 已啟用。');
        result = await quiet({ quietPrompt: prompt, responseLength: Number(manual.responseLength || 180), removeReasoning: true, trimToSentence: true });
      }
      source = '沿用目前酒館連線';
    }
    var text = cleanGeneratedLetter(result).replace(/\s+/g, ' ').replace(/^[「『“\"]+|[」』”\"]+$/g, '').trim();
    text = clipText(text, Number(manual.maxChars) || 80);
    var at = new Date().toISOString();
    savePetState({ lastGeneratedDeskLine: text, lastGeneratedDeskLineSource: source, lastGeneratedDeskLineAt: at, lastInteractionAt: Date.now(), deskLineError: '' });
    showWhisper({ id: 'manual-' + at, kind: 'manual-line', text: text, mood: letterMood(text, 'tease'), action: 'home' }, { visibleMs: 14000 });
    return { text: text, source: source, generated: true };
  }

  function stopWhisperScheduler() {
    host.clearInterval(dialogueRuntime.interval);
    host.clearTimeout(dialogueRuntime.initial);
    host.clearTimeout(dialogueRuntime.hide);
    dialogueRuntime.interval = 0;
    dialogueRuntime.initial = 0;
    dialogueRuntime.hide = 0;
  }

  function startWhisperScheduler() {
    stopWhisperScheduler();
    syncHiddenLetters();
    var config = dialogueConfig();
    dialogueRuntime.initial = host.setTimeout(function() { evaluateWhisper({ reason: 'initial' }); }, Number(config.cooldowns.initialDelayMs) || 35000);
    dialogueRuntime.interval = host.setInterval(function() { evaluateWhisper({ reason: 'timer' }); }, Number(config.cooldowns.schedulerMs) || 60000);
  }

