    body.innerHTML = '<div class="jn-copy">' + escapeHtml(line).replace(/\n/g, '<br>') + '<br><br>—— 姜南</div><div class="jn-note">書信來源：' + escapeHtml(source) + (mode === 'local' ? '<br>目前使用不耗生成的本地字條；藏信也全部在本機解鎖。' : '<br>生成只回到這個 HTML，不會新增聊天樓層。') + '</div>' + hiddenHtml + '<div id="jn-letter-error" class="jn-error" hidden></div><div class="jn-actions">' + (canGenerate ? '<button class="jn-btn primary" id="jn-generate-letter">讓姜南再留一封</button><button class="jn-btn" id="jn-generate-desk-line">叫他在桌邊說一句<small>會使用所選連線並消耗一次生成；只顯示氣泡，不送聊天。</small></button>' : '') + '<button class="jn-btn" data-page="settings">書信與氣泡設定</button><button class="jn-btn" data-page="home">收起來</button></div>';
