      var detail = [profile.name, profile.model || profile.api].filter(Boolean).join(' · ');
      return '<option value="' + escapeHtml(profile.id) + '"' + (String(state.letterProfileId || '') === profile.id ? ' selected' : '') + '>' + escapeHtml(detail) + '</option>';
    }).join('');
    var body = modalShell('相處設定', '設定跟著這個聊天走，不使用瀏覽器持久儲存，也不存放任何金鑰。');
    var bubbleEnabled = typeof state.bubbleEnabled === 'boolean' ? state.bubbleEnabled : dialogueConfig().defaults.bubbleEnabled !== false;
    var knockEnabled = typeof state.knockEnabled === 'boolean' ? state.knockEnabled : dialogueConfig().defaults.knockEnabled !== false;
    body.innerHTML =
      '<div class="jn-section-title"><h3>桌寵尺寸</h3><p>' + sizeDevice + '尺寸獨立保存</p></div>' +
      '<div class="jn-size-control"><label class="jn-size-label" for="jn-pet-size-range"><span>姜南在桌邊的大小</span><output id="jn-pet-size-value" for="jn-pet-size-range">' + sizePercent + '%</output></label><input id="jn-pet-size-range" type="range" min="60" max="180" step="10" value="' + sizePercent + '" aria-label="桌寵尺寸百分比"><div class="jn-size-buttons"><button class="jn-btn" id="jn-pet-size-minus" type="button" aria-label="縮小桌寵">－</button><button class="jn-btn" id="jn-pet-size-reset" type="button">重設 100%</button><button class="jn-btn" id="jn-pet-size-plus" type="button" aria-label="放大桌寵">＋</button></div><div class="jn-note">調整後立即預覽；範圍 60%～180%。手機與桌面各記一份，尺寸改變後仍會重新避開輸入框與螢幕邊界。</div></div>' +
      '<div class="jn-section-title"><h3>書信生成</h3><p>只改桌邊信紙，不新增聊天樓層</p></div>' +
      '<div class="jn-form"><div class="jn-field"><label for="jn-letter-mode">書信來源</label><select id="jn-letter-mode"><option value="local"' + (mode === 'local' ? ' selected' : '') + '>使用本地信件（零生成）</option><option value="current"' + (mode === 'current' ? ' selected' : '') + '>沿用目前酒館連線</option><option value="profile"' + (mode === 'profile' ? ' selected' : '') + '>指定副連線（Connection Profile）</option></select></div><div class="jn-field" id="jn-letter-profile-field"' + (mode === 'profile' ? '' : ' hidden') + '><label for="jn-letter-profile">副連線設定檔</label><select id="jn-letter-profile">' + profileOptions + '</select></div><div class="jn-note">副連線直接讀取酒館 Connection Profiles。請先在酒館建立連線設定檔；桌寵只記住 profile ID，不複製 API 網址或金鑰。' + (profiles.length ? '<br>目前讀到 ' + profiles.length + ' 個設定檔。' : '<br>目前沒有讀到設定檔；可先使用本地信件或目前酒館連線。') + '</div></div>' +
      '<div class="jn-section-title"><h3>桌邊互動</h3><p>自動內容一律零生成</p></div>' +
      '<div class="jn-actions"><button class="jn-btn" id="jn-bubbles">' + (bubbleEnabled ? '關閉情境氣泡' : '開啟情境氣泡') + '<small>時間、MVU、遊戲、未讀信與停留狀態；不呼叫模型。</small></button><button class="jn-btn" id="jn-knock">' + (knockEnabled ? '關閉夜間敲窗' : '開啟夜間敲窗') + '<small>22:00～03:00 生效，至少間隔 45 分鐘。</small></button><button class="jn-btn" id="jn-night">' + (state.night === true ? '關閉夜間模式' : '開啟夜間模式') + '<small>降低桌寵亮度與飽和度。</small></button><button class="jn-btn" id="jn-reset-position">讓姜南回到右下角<small>只重設位置，不碰聊天或 MVU。</small></button></div>' +
      '<div class="jn-rule">桌邊氣泡、未讀提醒、藏信與敲窗只從角色設定檔和本聊天狀態挑句，不會暗中生成。只有妳在信件頁親手按「叫他在桌邊說一句」才會使用上方所選連線。已內嵌姜南 8×12／96 幀透明動畫圖集，信件語氣會映射到不同動作。</div>' +
      '<div class="jn-actions"><button class="jn-btn" data-page="letters">回到信紙</button><button class="jn-btn" data-page="home">返回</button></div>';
