    function updateSize(nextValue) {
      var next = applyPetSize(nextValue, true);
      sizeRange.value = String(next);
      sizeValue.textContent = next + '%';
      schedulePetLayout();
    }
    sizeRange.addEventListener('input', function(event) { updateSize(event.currentTarget.value); });
    body.querySelector('#jn-pet-size-minus').addEventListener('click', function() { updateSize(Number(sizeRange.value) - 10); });
    body.querySelector('#jn-pet-size-reset').addEventListener('click', function() { updateSize(100); });
