      savePetState({ letterProfileId: event.currentTarget.value });
    });
    body.querySelector('#jn-bubbles').addEventListener('click', function() { savePetState({ bubbleEnabled: !bubbleEnabled }); mountPet(); openSettings(); });
    body.querySelector('#jn-knock').addEventListener('click', function() { savePetState({ knockEnabled: !knockEnabled }); mountPet(); openSettings(); });
    body.querySelector('#jn-night').addEventListener('click', function() { savePetState({ night: state.night !== true }); mountPet(); openSettings(); });
    body.querySelector('#jn-reset-position').addEventListener('click', function() { savePetState({ x: null, y: null }); mountPet(); notify('姜南已回到右下角。', 'success'); });
  }

  async function openDiagnostics() {
    var engine = gameEngine() || await connectGameEngine(1200);
    var checks = [
      ['TavernHelper 按鈕事件', !!findApi('getButtonEvent') && !!findApi('eventOn')],
      ['MVU', !!findValue('Mvu')],
      ['真骰引擎 v2', !!engine],
      ['聊天變量', !!findApi('getVariables') && !!findApi('insertOrAssignVariables')],
      ['酒館指令', !!findApi('triggerSlash')],
      ['書信副連線', getConnectionProfiles().length > 0],
      ['桌邊對話設定', dialogueConfig().schemaVersion !== 'fallback']
    ];
    var body = modalShell('哪裡斷線了', '紅燈不裝死；依照缺失項目重新啟用對應腳本或擴充。');
    var engineHelp = engine ? '真骰引擎已透過 TavernHelper shared global 接通。' : engineConnection.status === 'bridge-missing' ? '找不到 TavernHelper 的跨腳本橋接；請確認酒館助手已啟用。' : '共享橋接已等待但未收到引擎；請確認卡內「真骰引擎」腳本已啟用，再重新載入聊天。';
    body.innerHTML = '<div class="jn-vitals">' + checks.map(function(item) { return '<div class="jn-vital"><span>' + item[0] + '</span><strong style="color:' + (item[1] ? '#8eb49e' : '#d98270') + '">' + (item[1] ? '已連線' : '未連線') + '</strong></div>'; }).join('') + '</div><div class="jn-rule">' + escapeHtml(engineHelp) + '<br>若 MVU 未連線：確認 MVU 與 TavernHelper 已安裝並啟用。</div><div class="jn-actions"><button class="jn-btn" data-page="diagnostics">重新偵測</button><button class="jn-btn" data-page="home">返回</button></div>';
    bindActions(body);
  }

  function showError(message) {
    var body = modalShell('連線沒有接好', message || '未知錯誤');
    body.innerHTML = '<div class="jn-error">' + escapeHtml(message || '未知錯誤') + '</div><div class="jn-actions"><button class="jn-btn" data-page="diagnostics">打開診斷</button><button class="jn-btn" data-page="home">返回</button></div>';
    bindActions(body);
  }

  function openPet(page) {
    if (!alive()) return false;
    if (page === 'games') openGames();
    else if (page === 'status') openStatus();
    else if (page === 'letters') openLetters();
    else if (page === 'settings') openSettings();
    else if (page === 'diagnostics') openDiagnostics();
    else openHome();
    return true;
  }

  function registerSlashEntry() {
    try {
      var Parser = findValue('SlashCommandParser');
      var Command = findValue('SlashCommand');
      if (Parser && typeof Parser.addCommandObject === 'function' && Command && typeof Command.fromProps === 'function') {
        Parser.addCommandObject(Command.fromProps({
          name: 'jiangnan', aliases: ['jn-pet'],
          callback: function() { openPet('games'); return ''; },
          returns: 'empty string; opens Jiangnan HTML without sending a message',
          helpString: '<div>開啟姜南遊戲與相處介面，不送出聊天訊息。</div>'
        }));
        return true;
      }
    } catch (e) { console.info('[姜南桌寵] modern slash registration skipped', e); }
    try {
      var legacy = findApi('registerSlashCommand');
      if (legacy) {
        legacy('jiangnan', function() { openPet('games'); return ''; }, ['jn-pet'], '開啟姜南 HTML，不送出訊息', true, true);
        return true;
      }
    } catch (e2) { console.info('[姜南桌寵] legacy slash registration skipped', e2); }
    return false;
  }

  async function setupQR(canRunCommand) {
    if (!canRunCommand) return;
    var slash = findApi('triggerSlash');
    if (!slash) return;
    try {
      var raw = await slash('/qr-set-list');
      var sets = [];
      try { sets = JSON.parse(raw || '[]'); } catch (e) {}
      if (!Array.isArray(sets)) sets = [];
      try { await slash('/qr-chat-set-off 姜南_洋樓_v4'); } catch (e1) {}
      if (sets.indexOf(QR_SET) < 0) {
        await slash('/qr-set-create nosend=true ' + QR_SET);
        await slash('/qr-create set="' + QR_SET + '" label="💌 姜南" title="開啟姜南的相處與遊戲介面，不送訊息" /jiangnan');
      }
      await slash('/qr-chat-set-on visible=true ' + QR_SET);
    } catch (e2) {
      console.info('[姜南桌寵] QR 自動建立失敗；TavernHelper 按鈕仍可使用', e2);
    }
  }

  function bindToolbar() {
    try {
      var on = findApi('eventOn'), getEvent = findApi('getButtonEvent');
      if (!on || !getEvent) throw new Error('button_api_unavailable');
      on(getEvent(BUTTON), function() { openPet('home'); });
    } catch (e) { notify('工具列按鈕沒有接上；桌面上的姜南仍可直接點。', 'warning'); }
  }

  var previous = globalThis[KEY];
  if (previous && typeof previous.destroy === 'function') {
    try { previous.destroy(); } catch (e) {}
  }
  var petApi = {
    token: token,
    assets: { spriteSheet: SPRITE_SHEET_URL, atlas: SPRITE_ATLAS },
    openPet: openPet,
    openGames: openGames,
    openGame: openGame,
    getConnectionProfiles: getConnectionProfiles,
    generateLetter: generateLetter,
    generateDeskLine: generateDeskLine,
    chooseContextWhisper: chooseContextWhisper,
    evaluateWhisper: evaluateWhisper,
    showWhisper: showWhisper,
    getUnlockedLetters: function() { return syncHiddenLetters().available.slice(); },
    openHiddenLetter: openHiddenLetter,
    setSizePercent: function(value) { var next = applyPetSize(value, true); schedulePetLayout(); return next; },
    setSpriteSequence: setSpriteSequence,
    close: closePet,
    destroy: function() {
      stopWhisperScheduler();
      clearPetLayout();
      cancelFrame(spriteAnimation.raf);
      spriteAnimation.raf = 0;
      var root = doc.getElementById(ROOT_ID), modal = doc.getElementById(MODAL_ID);
      if (root) root.remove(); if (modal) modal.remove();
    }
  };
  globalThis[KEY] = petApi;
  var publishGlobal = findApi('initializeGlobal');
  if (publishGlobal) publishGlobal(PET_GLOBAL, petApi);
  else {
    try { host[PET_GLOBAL] = petApi; } catch (e) {}
  }

  mountPet();
  bindToolbar();
  setupQR(registerSlashEntry());
  connectGameEngine(10000);
  console.info('[姜南桌寵] v2.6 ready; bridge=' + GAME_ENGINE_GLOBAL + '; dialogue=' + dialogueConfig().schemaVersion + '; auto-generation=false; letter-profiles=' + getConnectionProfiles().length + '; user-size=60..180; mobile-safe-area=true; embedded=96-frame-webp; qr=' + QR_SET);
});

const JIANGNAN_STATUS_PLACEHOLDER = '<StatusPlaceHolderImpl/>';

async function ensureJiangnanStatusPlaceholder(messageId) {
  const message = getChatMessages(messageId)[0];
  if (!message || message.role !== 'assistant') {
    return;
  }

  const currentText = String(message.message ?? '');
  if (currentText.includes(JIANGNAN_STATUS_PLACEHOLDER)) {
    return;
  }

  const nextText = `${currentText.trimEnd()}\n\n${JIANGNAN_STATUS_PLACEHOLDER}`;
  await setChatMessages(
    [{ message_id: messageId, message: nextText }],
    { refresh: 'affected' },
  );
}

eventOn(tavern_events.MESSAGE_RECEIVED, ensureJiangnanStatusPlaceholder);
